from fractions import Fraction


def compute_data_mix(weights: dict[str, float], total_tokens: int) -> dict[str, int]:
    """Given dataset weights and total token count,
    return token allocation per dataset.
    Weights are normalized to sum to 1.0."""
    if not weights:
        return {}
    exact = {name: Fraction(str(w)) for name, w in weights.items()}
    total_w = sum(exact.values())
    if total_w <= 0:
        raise ValueError("weights must sum to a positive value")

    shares = {name: w / total_w * total_tokens for name, w in exact.items()}
    alloc = {name: int(s) for name, s in shares.items()}  # floor (non-negative)

    # Distribute leftover tokens by largest fractional remainder
    leftover = total_tokens - sum(alloc.values())
    order = sorted(shares, key=lambda n: shares[n] - alloc[n], reverse=True)
    for name in order[:leftover]:
        alloc[name] += 1
    return alloc


# Test
mix = compute_data_mix(
    {"FineWeb-Edu": 0.70, "Stack-Edu-Python": 0.20, "FineMath": 0.10},
    total_tokens=11_000_000_000_000
)
for name, tokens in mix.items():
    print(f"{name}: {tokens:,} tokens")
